(function(root){const score=(x,b,t,d)=>{if([x,b,t].some(v=>v===''||v===null||v===undefined||!Number.isFinite(Number(v))))return{error:'Bitte drei gültige Zahlen eingeben.'};[x,b,t]=[x,b,t].map(Number);if(d==='lower'&&b<=t)return{error:'B muss größer als T sein.'};if(d==='higher'&&t<=b)return{error:'T muss größer als B sein.'};if(!['lower','higher'].includes(d))return{error:'Ungültige Richtung.'};return{value:100*Math.max(0,Math.min(1,d==='lower'?(b-x)/(b-t):(x-b)/(t-b)))}};const stats=(data,id)=>{let r={num:0,qual:0,plan:0,gap:0,total:0};data.questions.filter(q=>['Ökologisch','Ökonomisch','Sozial'].includes(q.dimension)).forEach(q=>{r[data.answers[id][q.id].status]++;r.total++});r.covered=r.num+r.qual+r.plan;return r};root.AppLogic={score,stats};if(typeof module!=='undefined')module.exports={score,stats}})(typeof window!=='undefined'?window:globalThis);
